const CACHE : & [u32] = & const_sort (& [2 , 3 , 1] , | a , b | a < b) ; const fn const_sort < F , const N : usize > (v : & [u32 ; N] , mut is_less : F) -> [u32 ; N] where F : FnMut (& u32 , & u32) -> bool , { let mut r = [0 ; N] ; let mut i = 0 ; while i < N { r [i] = v [i] ; i += 1 ; } let mut i = 1 ; while i < N { if is_less (& r [i] , & r [i - 1]) { let tmp = r [i] ; r [i] = r [i - 1] ; let mut j = i - 1 ; while j > 0 && is_less (& tmp , & r [j - 1]) { r [j] = r [j - 1] ; j -= 1 ; } r [j] = tmp ; } i += 1 ; } r }